//! Differential tests: replays `golden/math.json`, generated by `model/gen_golden.py` from the
//! reference model (`model/v201`), through the pure core and requires exact equality on every
//! row. Do not edit the JSON by hand; regenerate it from the model.
#![allow(
    clippy::arithmetic_side_effects,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::unwrap_used
)]

use crate::math::{
    PriceRefs,
    coverage::{long_need, short_need},
    curve::{ConstantProduct as Cp, Curve, FEE_DEN, FEE_NUM, PoolState},
    fixed::{Price, Q64},
    health::{HealthTerms, long_health_value, short_health_cost, verdict},
    interest::{BLOCKS_PER_DAY, accrue, interest_for_blocks},
    pace::up_budget,
};
use crate::params::{LendingParams, LongParams, ShortParams};
use serde_json::Value;

/// Row counts written by `gen_golden.py`; a silently shorter file must not pass.
const CURVE_QUOTE_ROWS: usize = 320;
const CURVE_PRICE_ROWS: usize = 200;
const COVERAGE_HEALTH_ROWS: usize = 180;
const INTEREST_ROWS: usize = 200;
const EXIT_ROWS: usize = 300;

fn golden() -> Value {
    serde_json::from_str(include_str!("golden/math.json")).expect("golden JSON parses")
}

fn rows<'a>(doc: &'a Value, section: &str) -> &'a Vec<Value> {
    doc[section].as_array().expect("section is an array")
}

fn num(v: &Value) -> u128 {
    v.as_str()
        .expect("decimal string")
        .parse()
        .expect("unsigned integer")
}

fn amount(v: &Value) -> u64 {
    u64::try_from(num(v)).expect("fits u64")
}

fn small(v: &Value) -> u32 {
    u32::try_from(v.as_u64().expect("JSON number")).expect("fits u32")
}

fn opt_num(v: &Value) -> Option<u128> {
    (!v.is_null()).then(|| num(v))
}

fn price(v: &Value) -> Price {
    Price::from_bits(num(v))
}

fn pool(row: &Value) -> PoolState {
    PoolState {
        tao: amount(&row["tao"]),
        alpha: amount(&row["alpha"]),
    }
}

fn pool_pair(v: &Value) -> Option<PoolState> {
    Some(PoolState {
        tao: amount(&v[0]),
        alpha: amount(&v[1]),
    })
}

#[test]
fn header_matches_the_core_constants() {
    let doc = golden();
    assert_eq!(doc["source"], "model/v201");
    assert_eq!(num(&doc["q64"]), Q64);
    assert_eq!(u128::from(doc["fee"][0].as_u64().unwrap()), FEE_NUM);
    assert_eq!(u128::from(doc["fee"][1].as_u64().unwrap()), FEE_DEN);
}

#[test]
fn curve_rows_match_the_model() {
    let doc = golden();
    let (mut quotes, mut prices) = (0, 0);
    for (i, row) in rows(&doc, "curve").iter().enumerate() {
        let p = pool(row);
        if row.get("price").is_some() {
            let target = price(&row["price"]);
            assert_eq!(Cp::spot(&p), price(&row["spot"]), "spot, row {i}");
            assert_eq!(
                Cp::pumped(&p, target),
                pool_pair(&row["pumped"]),
                "pumped, row {i}"
            );
            assert_eq!(
                Cp::dumped(&p, target),
                pool_pair(&row["dumped"]),
                "dumped, row {i}"
            );
            // The model caps at spot * (1e4 + 5) / 1e4: the launch pace.
            assert_eq!(
                up_budget::<Cp>(&p, 5),
                amount(&row["alpha_for_up_impact"]),
                "alpha_for_up_impact, row {i}"
            );
            prices += 1;
        } else {
            let (a, tin) = (amount(&row["a"]), amount(&row["tin"]));
            assert_eq!(
                Cp::out_alpha_for_tao(&p, tin),
                amount(&row["out_alpha_for_tao"]),
                "out_alpha_for_tao, row {i}"
            );
            assert_eq!(
                Cp::out_tao_for_alpha(&p, a),
                amount(&row["out_tao_for_alpha"]),
                "out_tao_for_alpha, row {i}"
            );
            assert_eq!(
                Cp::tao_in_for_alpha(&p, a),
                opt_num(&row["tao_in_for_alpha"]),
                "tao_in_for_alpha, row {i}"
            );
            assert_eq!(
                Cp::buy_cost_nofee(&p, a),
                opt_num(&row["buy_cost_nofee"]),
                "buy_cost_nofee, row {i}"
            );
            assert_eq!(
                Cp::sell_proceeds_nofee(&p, a),
                amount(&row["sell_proceeds_nofee"]),
                "sell_proceeds_nofee, row {i}"
            );
            quotes += 1;
        }
    }
    assert_eq!((quotes, prices), (CURVE_QUOTE_ROWS, CURVE_PRICE_ROWS));
}

#[test]
fn coverage_and_health_rows_match_the_model() {
    let doc = golden();
    let (sp, lp) = (ShortParams::default(), LongParams::default());
    let all = rows(&doc, "coverage_health");
    for (i, row) in all.iter().enumerate() {
        let p = pool(row);
        let refs = PriceRefs {
            spot: price(&row["spot"]),
            twap: price(&row["twap"]),
            sma: price(&row["sma"]),
        };
        assert_eq!(Cp::spot(&p), refs.spot, "spot, row {i}");

        let short = &row["short"];
        let (q, book) = (amount(&short["q"]), amount(&short["book"]));
        assert_eq!(
            short_need::<Cp>(&p, &refs, q, book, sp.stress_bps, sp.stress_slope_bps)
                .map(u128::from),
            opt_num(&short["need"]),
            "short need, row {i}"
        );
        assert_eq!(
            short_health_cost::<Cp>(&p, &refs, book, q).map(u128::from),
            opt_num(&short["health_cost"]),
            "short health cost, row {i}"
        );

        let long = &row["long"];
        let (a, book, debt) = (
            amount(&long["a"]),
            amount(&long["book"]),
            amount(&long["debt"]),
        );
        assert_eq!(
            long_need::<Cp>(&p, &refs, debt, a, book, lp.stress_bps),
            amount(&long["need"]),
            "long need, row {i}"
        );
        assert_eq!(
            long_health_value::<Cp>(&p, &refs, book, a),
            amount(&long["health_value"]),
            "long health value, row {i}"
        );
    }
    assert_eq!(all.len(), COVERAGE_HEALTH_ROWS);
}

#[test]
fn interest_rows_match_the_model() {
    let doc = golden();
    let all = rows(&doc, "interest");
    for (i, row) in all.iter().enumerate() {
        let (notional, apr) = (amount(&row["notional"]), small(&row["apr_bps"]));
        let accrued = accrue(
            notional,
            apr,
            row["blocks"].as_u64().unwrap(),
            num(&row["rem_in"]),
        );
        assert_eq!(accrued.owed, amount(&row["owed"]), "owed, row {i}");
        assert_eq!(
            accrued.remainder,
            num(&row["rem_out"]),
            "remainder, row {i}"
        );
        assert_eq!(
            interest_for_blocks(notional, apr, BLOCKS_PER_DAY),
            amount(&row["day"]),
            "day interest, row {i}"
        );
    }
    assert_eq!(all.len(), INTEREST_ROWS);
}

#[test]
fn exit_rows_match_the_model() {
    let doc = golden();
    let all = rows(&doc, "exit");
    for (i, row) in all.iter().enumerate() {
        let equity: i128 = row["equity"].as_str().unwrap().parse().unwrap();
        let terms = HealthTerms {
            apr_bps: LendingParams::default().apr_bps,
            min_interest_cover_blocks: LendingParams::default().min_interest_cover_blocks,
            equity_floor: amount(&row["floor"]),
            exit_hysteresis_bps: small(&row["h_bps"]),
        };
        let v = verdict(
            Some(equity),
            amount(&row["at_risk"]),
            amount(&row["collateral"]),
            amount(&row["cover"]),
            &terms,
        );
        assert_eq!(
            v.triggered,
            row["triggered"].as_bool().unwrap(),
            "triggered, row {i}"
        );
        assert_eq!(
            v.may_exit,
            row["may_exit"].as_bool().unwrap(),
            "may_exit, row {i}"
        );
    }
    assert_eq!(all.len(), EXIT_ROWS);
}
